#!/usr/bin/env python3
"""Size and health of a codebase in plain numbers.

Counts files and lines per language, lists the 10 biggest source files, counts TODO, FIXME and
HACK markers in comments, compares test files with other code files, and checks for a README at
the top, an .env.example, a lockfile, CI and tests. Code files over 500 lines make one low
finding together: long files are hard to read and to change safely.

Walks every folder except .git, node_modules, vendor, virtualenvs (any folder with a pyvenv.cfg),
build, cache and collected-static folders and forge-work; skips symlinks and binary files. Files
that were generated or copied in from a library are listed apart and left out of the counts: a
"Generated by" or "DO NOT EDIT" line, a /*! licence banner or a webpack bundle at the top, a
database dump, or minified code (lines of 300 characters on average). Of a file over 1 MB only
the lines are counted. It never prints file contents, only names and numbers. A requirements.txt
counts as a lockfile when every package in it is pinned (name==1.2.3).

Usage:
    python3 inventory.py .                the project in the current folder
    python3 inventory.py ../shop --json   machine-readable output

Exit codes:
    0  done (long files are a low finding; they never fail the run)
    2  bad usage, or PATH is not a folder
"""

import argparse
import fnmatch
import json
import os
import posixpath
import re
import sys

MAX_BYTES = 1024 * 1024  # read this much at a time; of a bigger file only the lines are counted
LONG_FILE = 500  # lines
BIGGEST = 10  # how many of the biggest files to list
SKIP_FOLDERS = {".git", "node_modules", "vendor", "venv", ".venv", "__pycache__", "dist", "build", ".next",
                ".nuxt", "out", "coverage", "storage/framework", ".cache", ".idea", ".vscode", "forge-work",
                "staticfiles"}  # staticfiles: Django's collectstatic copies, not the project's own code
# Code counts for the test ratio and for long files. Markup, styles and SQL count for size only.
CODE = {".php": "PHP", ".py": "Python", ".js": "JavaScript", ".jsx": "JavaScript", ".mjs": "JavaScript",
        ".cjs": "JavaScript", ".ts": "TypeScript", ".tsx": "TypeScript", ".vue": "Vue", ".svelte": "Svelte",
        ".astro": "Astro", ".rb": "Ruby", ".go": "Go", ".java": "Java", ".kt": "Kotlin", ".rs": "Rust",
        ".cs": "C#", ".sh": "Shell"}
MARKUP = {".html": "HTML", ".htm": "HTML", ".twig": "Twig", ".css": "CSS", ".scss": "SCSS",
          ".sass": "Sass", ".less": "Less", ".sql": "SQL"}
TEST_FOLDERS = {"tests", "test", "__tests__", "spec", "specs", "e2e", "cypress"}
TEST_NAME = re.compile(r"^tests?\.py$|^test_.*\.py$|_test\.(py|go)$|\.(test|spec)\.[cm]?[jt]sx?$"
                       r"|Test\.php$|_spec\.rb$")
MARKER = re.compile(r"\b(TODO|FIXME|HACK)\b")
# Where a comment starts: # // /* <!-- {{-- or, at the start of a line, * (inside /* */) or -- (SQL).
COMMENT_START = re.compile(r"^\s*(\*|--)|(^|\s)(#|//|/\*|<!--|\{\{--)")
# Signs in the first 1 KB that a file was generated or copied in from a library.
GENERATED = re.compile(r"@generated|DO NOT EDIT|\bGenerated (by|for|from)\b|webpackBootstrap|\A\s*/\*(!|\*{5}/)"
                       r"|^-- (MySQL|MariaDB) dump|^-- PostgreSQL database dump", re.M)
MINIFIED = 300  # characters per line on average
LOCKFILES = {"composer.lock", "package-lock.json", "npm-shrinkwrap.json", "yarn.lock", "pnpm-lock.yaml",
             "bun.lock", "bun.lockb", "poetry.lock", "Pipfile.lock", "uv.lock"}
ENV_EXAMPLES = {".env.example", ".env.sample", ".env.dist", ".env.template", "env.example"}
# CI services and the file each one reads from the top folder (the same table as detect.py's stacks.json).
CI_FILES = {"GitHub Actions": ".github/workflows/*.y*ml", "GitLab CI": ".gitlab-ci.y*ml",
            "Bitbucket Pipelines": "bitbucket-pipelines.y*ml", "CircleCI": ".circleci/config.y*ml",
            "Jenkins": "Jenkinsfile", "Azure Pipelines": "azure-pipelines.y*ml"}
LONG_WHY = "long files are hard to read, test and change without breaking something else"
LONG_FIX = "split each one by job (one class, component or module per job) the next time you change it"


def language_of(name):
    """(language, is it code) for a file name. (None, False) for files that are not source."""
    if name.endswith(".blade.php"):
        return "Blade", False
    if name.endswith((".min.js", ".min.css")):
        return None, False
    extension = os.path.splitext(name)[1].lower()
    return (CODE[extension], True) if extension in CODE else (MARKUP.get(extension), False)


def is_test_file(path):
    """True for tests: files in a tests folder (tests/, __tests__/, e2e/) or with a test name
    (test_x.py, x.test.ts, XTest.php)."""
    parts = path.split("/")
    return bool(TEST_FOLDERS & set(parts[:-1])) or bool(TEST_NAME.search(parts[-1]))


def is_pinned(text):
    """True when every package in a requirements.txt is pinned to one version (name==1.2.3)."""
    lines = [line.split("#")[0].strip() for line in text.splitlines()]
    packages = [line for line in lines if line and not line.startswith("-")]
    return bool(packages) and all("==" in line for line in packages)


def markers_in(text):
    """The TODO, FIXME and HACK markers in the comments of TEXT. A TODO in code (an enum value
    Status.TODO) is no marker."""
    found = []
    for line in re.findall(r"^.*\b(?:TODO|FIXME|HACK)\b.*$", text, re.M):  # only lines with a marker
        start = COMMENT_START.search(line)
        found += MARKER.findall(line, start.start()) if start else []
    return found


def walk(root, unreadable):
    """Yield the relative path ('app/x.php') of every regular file under ROOT, minus skipped folders,
    virtualenvs and symlinks. Folders that cannot be opened are added to UNREADABLE."""
    for folder, subfolders, names in os.walk(root, onerror=lambda error: unreadable.append(error.filename)):
        relative = "" if folder == root else os.path.relpath(folder, root).replace(os.sep, "/")
        here = posixpath.basename(relative)
        subfolders[:] = sorted(name for name in subfolders if name not in SKIP_FOLDERS
                               and here + "/" + name not in SKIP_FOLDERS
                               and not os.path.isfile(os.path.join(folder, name, "pyvenv.cfg")))
        for name in sorted(names):  # regular files only: reading a pipe would never end
            if os.path.isfile(os.path.join(folder, name)) and not os.path.islink(os.path.join(folder, name)):
                yield posixpath.join(relative, name)


def measure(root, path, stats):
    """(lines, text, generated) for a file; the text is None when it is over 1 MB. None when the file
    is binary or cannot be read (counted in STATS)."""
    try:
        with open(os.path.join(root, path), "rb") as handle:
            data = handle.read(MAX_BYTES + 1)
            if b"\0" in data[:8192]:  # a NUL byte: binary
                stats["skipped"] += 1
                return None
            lines, last = data.count(b"\n"), data[-1:]
            for chunk in iter(lambda: handle.read(MAX_BYTES), b""):  # the rest of a big file, a chunk at a time
                lines, last = lines + chunk.count(b"\n"), chunk[-1:]
    except OSError:
        stats["unreadable"].append(path)
        return None
    lines += 1 if last not in (b"", b"\n") else 0  # a last line without a line break counts too
    minified = len(data) > 2000 and len(data) / max(lines, 1) > MINIFIED
    generated = minified or GENERATED.search(data[:1024].decode("utf-8", "replace")) is not None
    return lines, data.decode("utf-8", "replace") if len(data) <= MAX_BYTES else None, generated


def checklist_hits(root, path, stats):
    """The checklist items this file shows are there: readme, env_example, lockfile, ci."""
    name, hits = posixpath.basename(path), []
    if "/" not in path and name.lower().startswith("readme"):
        hits.append("readme")
    if name in ENV_EXAMPLES:
        hits.append("env_example")
    if any(fnmatch.fnmatchcase(path, pattern) for pattern in CI_FILES.values()):
        hits.append("ci")
    if name in LOCKFILES:
        hits.append("lockfile")
    elif re.match(r"requirements.*\.txt$", name) and is_pinned((measure(root, path, stats) or (0, ""))[1] or ""):
        hits.append("lockfile")
    return hits


def long_files_finding(sources):
    """One low finding that lists every code file over LONG_FILE lines, or None."""
    long_files = [{"path": s["path"], "lines": s["lines"]} for s in sources if s["code"] and s["lines"] > LONG_FILE]
    if not long_files:
        return None
    return {"severity": "low", "title": "%s over %d lines" % (plural(len(long_files), "code file"), LONG_FILE),
            "where": ", ".join(item["path"] for item in long_files), "why": LONG_WHY, "fix": LONG_FIX,
            "files": long_files}


def inventory(root):
    """Walk ROOT and count. Returns the dict that --json prints."""
    stats = {"files": 0, "skipped": 0, "unreadable": [], "generated": []}
    languages, sources, markers = {}, [], {"TODO": 0, "FIXME": 0, "HACK": 0, "files": 0}
    tests, other_code = [], 0
    present = {"readme": [], "env_example": [], "lockfile": [], "ci": []}
    for path in walk(root, stats["unreadable"]):
        stats["files"] += 1
        for key in checklist_hits(root, path, stats):
            present[key].append(path)
        language, is_code = language_of(posixpath.basename(path))
        measured = measure(root, path, stats) if language else None
        if measured and measured[2]:  # generated or from a library: listed apart, not counted
            stats["generated"].append(path)
        if not measured or measured[2]:
            continue
        lines, text = measured[0], measured[1] or ""
        files_and_lines = languages.setdefault(language, [0, 0])
        files_and_lines[0] += 1
        files_and_lines[1] += lines
        sources.append({"path": path, "lines": lines, "language": language, "code": is_code})
        found = markers_in(text)
        for word in found:
            markers[word] += 1
        markers["files"] += 1 if found else 0
        if is_code and is_test_file(path):
            tests.append(path)
        elif is_code:
            other_code += 1
    sources.sort(key=lambda source: (-source["lines"], source["path"]))
    findings = [finding for finding in [long_files_finding(sources)] if finding]
    ratio = round(len(tests) / other_code, 2) if other_code else None
    checklist = {key: {"present": bool(paths), "files": paths} for key, paths in present.items()}
    checklist["tests"] = {"present": bool(tests), "files": tests[:3]}  # a few examples are enough
    by_size = sorted(languages.items(), key=lambda item: (-item[1][1], item[0]))  # most lines first
    return {"path": os.path.abspath(root),
            "files": {"seen": stats["files"], "source": len(sources), "skipped": stats["skipped"],
                      "generated": stats["generated"], "unreadable": stats["unreadable"]},
            "languages": [{"language": name, "files": counts[0], "lines": counts[1]} for name, counts in by_size],
            "biggest": [{"path": s["path"], "lines": s["lines"]} for s in sources[:BIGGEST]],
            "markers": markers,
            "tests": {"test_files": len(tests), "other_code_files": other_code, "tests_per_code_file": ratio},
            "checklist": checklist, "findings": findings,
            "summary": {"critical": 0, "high": 0, "medium": 0, "low": len(findings), "total": len(findings)}}


def plural(count, word):
    """'1 file', '3 files', '1,204 lines'."""
    return "{:,} {}{}".format(count, word, "" if count == 1 else "s")


def format_human(result):
    """The plain-text report. What does not print shows as an escape (\\n): a file name cannot add lines."""
    files, generated = result["files"], result["files"]["generated"]
    lines = ["Inventory of " + result["path"],
             "Files: %d seen, %d source files counted, %d skipped (binary), %d generated or from a library"
             % (files["seen"], files["source"], files["skipped"], len(generated)), "",
             "%-14s %7s %9s" % ("Language", "Files", "Lines")]
    for row in result["languages"]:
        lines.append("%-14s %7d %9s" % (row["language"], row["files"], "{:,}".format(row["lines"])))
    total = sum(row["lines"] for row in result["languages"])
    lines += ["%-14s %7d %9s" % ("Total", files["source"], "{:,}".format(total)), "",
              "Biggest source files (lines):"]
    lines += ["%9s  %s" % ("{:,}".format(big["lines"]), big["path"]) for big in result["biggest"]] or ["  none"]
    if generated:
        more = " and %d more" % (len(generated) - 5) if len(generated) > 5 else ""
        lines += ["", "Left out as generated or from a library: " + ", ".join(generated[:5]) + more]
    markers, tests = result["markers"], result["tests"]
    lines += ["", "Markers: %d TODO, %d FIXME, %d HACK, in %s"
              % (markers["TODO"], markers["FIXME"], markers["HACK"], plural(markers["files"], "file"))]
    if tests["test_files"] and tests["other_code_files"]:
        per = "1 test file per %.1f code files" % (tests["other_code_files"] / float(tests["test_files"]))
    else:
        per = "no test files" if not tests["test_files"] else "no other code files"
    lines.append("Tests:   %s, %s: %s" % (plural(tests["test_files"], "test file"),
                                          plural(tests["other_code_files"], "other code file"), per))
    lines += ["", "Checklist:"]
    for key, label in [("readme", "README"), ("env_example", ".env.example"), ("lockfile", "lockfile"),
                       ("ci", "CI"), ("tests", "tests")]:
        item = result["checklist"][key]
        shown = " (%s)" % ", ".join(item["files"][:3]) if item["files"] else ""
        lines.append("  %-3s  %s%s" % ("yes" if item["present"] else "no", label, shown))
    lines.append("")
    for finding in result["findings"]:
        where = ["%s (%s)" % (item["path"], plural(item["lines"], "line")) for item in finding["files"]]
        where = where[:BIGGEST] + (["and %d more" % (len(where) - BIGGEST)] if len(where) > BIGGEST else [])
        lines += ["LOW       " + finding["title"], "          where: " + where[0]]
        lines += ["                 " + item for item in where[1:]]
        lines += ["          why:   " + finding["why"], "          fix:   " + finding["fix"], ""]
    count = len(result["findings"])
    lines.append("%s: %d low." % (plural(count, "finding"), count) if count else "No findings.")
    if files["unreadable"]:
        lines.append("Could not read: " + ", ".join(files["unreadable"]))
    return "\n".join("".join(c if c.isprintable() else repr(c)[1:-1] for c in line) for line in lines)


def main(argv=None):
    """Run from the command line. Returns the exit code: 0, or 2 for a bad path."""
    parser = argparse.ArgumentParser(description="Size and health of a codebase in plain numbers.")
    parser.add_argument("path", help="the project folder")
    parser.add_argument("--json", action="store_true", help="print machine-readable JSON")
    args = parser.parse_args(argv)
    if not os.path.isdir(args.path):
        print("error: %s is not a folder that exists" % args.path, file=sys.stderr)
        return 2
    result = inventory(args.path)
    print(json.dumps(result, indent=2) if args.json else format_human(result))
    return 0


if __name__ == "__main__":
    sys.exit(main())
